function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1) return 'grid needs at least one row.';
  const n = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (n < 1) return 'Each row needs at least one cell.';
  if (grid.some(row => !Array.isArray(row) || row.length !== n)) return 'All rows must have the same length.';
  if (grid.length * n < 2) return 'grid needs at least 2 cells.';
  if (grid.length * n > 100000) return 'grid has at most 10^5 cells.';
  if (grid.some(row => row.some(v => v !== 0 && v !== 1))) return 'Every cell is 0 or 1.';
  if (grid[0][0] !== 0 || grid[grid.length - 1][n - 1] !== 0) return 'The top-left and bottom-right cells must be 0.';
  return null;
}

