function minimumObstacles(grid) {
  // Relax every cell from its neighbours until nothing improves (Bellman-Ford on the grid).
  const m = grid.length, n = grid[0].length;
  const best = grid.map(row => row.map(() => Infinity));
  best[0][0] = 0;
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i < m; i++) {
      for (let j = 0; j < n; j++) {
        const around = [i > 0 ? best[i - 1][j] : Infinity, i < m - 1 ? best[i + 1][j] : Infinity, j > 0 ? best[i][j - 1] : Infinity, j < n - 1 ? best[i][j + 1] : Infinity];
        const value = Math.min(...around) + grid[i][j];
        if (value < best[i][j]) { best[i][j] = value; changed = true; }
      }
    }
  }
  return best[m - 1][n - 1];
}

