function generate(rand, size) {
  let m, n;
  if (size === 'large') {
    m = 100;
    n = 100;
  } else {
    do {
      m = 1 + Math.floor(rand() * 5);
      n = 1 + Math.floor(rand() * 5);
    } while (m * n < 2);
  }
  const density = 0.2 + rand() * 0.6;
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)));
  grid[0][0] = 0;
  grid[m - 1][n - 1] = 0;
  return [grid];
}
